/**
 * RPC stubs of the server's `strip-metadata` actions
 * (server/src/actions/strip_metadata.rs): the account's "Remove metadata from
 * files on upload" switch, docs/SKELETON.md section 9 item 47. Not upstream, so
 * not generated by scripts/gen-actions.mjs; written the same way.
 */
import { callAction } from "../runtime/rpc";

/** Why a file uploaded with the switch on kept its metadata (`media::strip::KeptReason`). */
export type KeptReason = "damaged" | "format" | "protected" | "signed" | "too-large" | "busy" | "tool";

/** One such file. */
export interface KeptFile {
  id: string;
  code: string;
  filename: string;
  ext: string;
  reason: KeptReason | string;
  /** ISO string. */
  createdAt: string;
}

/** The Settings card (server/src/data/strip_metadata.rs `StripStatus`). */
export interface StripStatus {
  enabled: boolean;
  /** Newest first, at most 20. */
  kept: KeptFile[];
  keptTotal: number;
  /** The file types the switch cleans. */
  formats: string[];
}

export async function loadStripMetadata(): Promise<StripStatus> {
  return callAction("strip-metadata", "loadStripMetadata", arguments);
}

// eslint-disable-next-line @typescript-eslint/no-unused-vars
export async function setStripMetadata(enabled: boolean): Promise<StripStatus> {
  return callAction("strip-metadata", "setStripMetadata", arguments);
}
